export var copyToClipboard = function copyToClipboard(event, content) {
  var field = document.createElement('textarea');
  event.currentTarget.parentNode.appendChild(field);
  field.textContent = content;
  field.select();
  document.execCommand('copy');
  event.currentTarget.parentNode.removeChild(field);
};
export var copyContentToClipboard = function copyContentToClipboard(content) {
  return function (event) {
    return copyToClipboard(event, content);
  };
};